def calculate_a(n_max):
    a = [0] * (n_max + 1)
    a[1] = 1
    a[2] = 1
    for n in range(3, n_max + 1):
        prev_a = a[n-1]
        a[n] = a[prev_a] + a[n - prev_a]
    return a

a_vals = calculate_a(100)
for n, val in enumerate(a_vals):
    if n > 0:
        print(f"a_{n} = {val}")
